package app.maine.android.vault

import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test
import java.io.File

/**
 * Interop proof: `vault-golden-v2.json` is generated by the Swift
 * implementation itself (apps/android/tools/make-golden-vault.swift, using
 * CryptoKit + PBKDF2-SHA256 600k). If this test passes, the Android vault
 * reads macOS vaults byte-for-byte: envelope, KDF, AAD, nonce layout.
 *
 * The fixture is a published throwaway test vector, never a real vault.
 */
class VaultGoldenTest {

    companion object {
        // Must match the password passed to make-golden-vault.swift.
        const val GOLDEN_PASSWORD = "golden-horse-battery-42"
    }

    @Test
    fun readsMacOSVault() {
        val fixture = File("src/test/resources/vault-golden-v2.json")
        assertTrue("run tools/make-golden-vault.swift: ${fixture.absolutePath}", fixture.exists())

        val copy = File.createTempFile("golden", ".maine")
        try {
            fixture.copyTo(copy, overwrite = true)
            val vault = VaultStore(copy)
            vault.unlock(GOLDEN_PASSWORD)

            val hosts = vault.hosts()
            assertEquals(2, hosts.size)
            val web = hosts.first { it.name == "Golden web" }
            assertEquals("203.0.113.10", web.hostname)
            assertEquals(2222, web.port)
            assertEquals("deploy", web.username)
            // Lowercase fixture IDs canonicalize to the uppercase form the
            // macOS client uses for password lookup.
            assertEquals("0F8FAD5B-D9CB-469F-A165-70867728950E", web.id)
            assertEquals("golden-password-1", vault.passwordFor(web.id))
            assertEquals(
                "golden-password-2",
                vault.passwordFor("6ba7b810-9dad-11d1-80b4-00c04fd430c8"),
            )

            val sessions = vault.savedSessions()
            assertEquals(1, sessions.size)
            assertEquals("Session 1", sessions[0].name)
            assertEquals("golden scrollback\n$ ", sessions[0].history)
            // Swift encodes Date as seconds since 2001-01-01, not Unix epoch:
            // 1,783,000,000.5 unix is 804,692,800.5 reference-date seconds.
            assertEquals(804692800.5, sessions[0].savedAt, 0.001)

            // And the round trip back stays readable.
            vault.saveHosts(hosts)
            assertEquals(2, VaultStore(copy).let {
                it.unlock(GOLDEN_PASSWORD)
                it.hosts()
            }.size)
        } finally {
            copy.delete()
        }
    }
}
